-- PT120-S3-Q3. Batch 08.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch08$PT120-S3-Q3$batch08$ AND q.stimulus=$batch08$According to the rules of the university’s housing lottery, the only students guaranteed dormitory rooms are fourth-year students. In addition, any fourth-year student on the dean’s list can choose a dormitory room before anyone who is not a fourth-year student.$batch08$ AND q.prompt=$batch08$Which one of the following inferences is most strongly supported by the rules described above?$batch08$ AND q.correct_choice=$batch08$D$batch08$) THEN RAISE EXCEPTION 'Question changed: PT120-S3-Q3'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch08$PT120-S3-Q3$batch08$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT120-S3-Q3'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch08$PT120-S3-Q3$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch08$Statements$batch08$, $batch08$Rule 1: only fourth-year students are guaranteed rooms. Rule 2: a fourth-year student on the dean's list chooses before anyone who isn't a fourth-year student.$batch08$), (1, $batch08$Evaluate$batch08$, $batch08$Diagram them. Rule 1: guaranteed → fourth-year. Note the direction: being a fourth-year doesn't guarantee a room. Rule 2 needs two things, fourth-year *and* dean's list, and then puts that student ahead of every non-fourth-year.$batch08$), (2, $batch08$Goal$batch08$, $batch08$Find a fourth-year on the dean's list placed ahead of someone who isn't a fourth-year.$batch08$)) v(position,label,body) WHERE q.qid=$batch08$PT120-S3-Q3$batch08$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch08$A$batch08$, $batch08$"Only fourth-years are guaranteed" doesn't mean every fourth-year is. We can't conclude Benizer isn't guaranteed, either. The rule is silent.$batch08$), ($batch08$B$batch08$, $batch08$Neither rule ranks fourth-years against each other. And if anything, it would be Naomi, not Ivan, who has the advantage.$batch08$), ($batch08$C$batch08$, $batch08$Halle is a third-year, and only fourth-years are guaranteed.$batch08$), ($batch08$D$batch08$, $batch08$Gerald is a fourth-year on the dean's list; Katrina isn't a fourth-year. Rule 2 puts Gerald first.$batch08$), ($batch08$E$batch08$, $batch08$Anissa meets Rule 2 and Jehan is a second-year, so Anissa goes first, not Jehan.$batch08$)) v(letter,body) WHERE q.qid=$batch08$PT120-S3-Q3$batch08$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
